export function normalizeCountryKey(value) {
  return String(value || '')
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-zA-Z0-9 ]/g, ' ')
    .toLowerCase()
    .replace(/\s+/g, ' ')
    .trim();
}

const _BY_NORMALIZED_NAME = Object.fromEntries(
  Object.entries(SECONDARY_SPORTS_BY_COUNTRY_NAME).map(([k, v]) => [normalizeCountryKey(k), v])
);

export function getSecondarySportRecord(countryName, countryCode) {
  const code = String(countryCode || '').toLowerCase();
  if (code && SECONDARY_SPORTS_BY_COUNTRY_CODE[code]) return SECONDARY_SPORTS_BY_COUNTRY_CODE[code];
  const key = normalizeCountryKey(countryName);
  return _BY_NORMALIZED_NAME[key] || null;
}
